import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAYS = {
    "mon", "monday",
    "tue", "tues", "tuesday",
    "wed", "weds", "wednesday",
    "thu", "thur", "thurs", "thursday",
    "fri", "friday",
    "sat", "saturday",
    "sun", "sunday",
}

_ORDINAL = r"(?:st|nd|rd|th)?"


def _iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _strip_weekday(t: str) -> str:
    # Remove a leading weekday name, e.g. "Tuesday, March 5, 2024" -> "March 5, 2024".
    m = re.fullmatch(r"([A-Za-z]+)\.?,?\s*(.+)", t)
    if m and m.group(1).lower() in _WEEKDAYS:
        return m.group(2).strip()
    return t


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    t = _strip_weekday(t)
    if not t:
        return "INVALID"

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Day-first numeric (ambiguous slash/dash/dot dates are read as DD/MM/YYYY)
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        return _iso(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Day, month name, year: "5 March 2024", "5-Mar-2024", "5th of March, 2024"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORDINAL + r"(?:\s+of)?[\s\-/.]*([A-Za-z]+)\.?[\s\-/.,]*(\d{4})",
        t,
    )
    if m:
        month = _month_number(m.group(2))
        if month:
            return _iso(int(m.group(3)), month, int(m.group(1)))
        return "INVALID"

    # Month name, day, year: "March 5, 2024", "Mar 5 2024", "March 5th 2024"
    m = re.fullmatch(
        r"([A-Za-z]+)\.?[\s\-/.]*(\d{1,2})" + _ORDINAL + r"[\s\-/.,]*(\d{4})",
        t,
    )
    if m:
        month = _month_number(m.group(1))
        if month:
            return _iso(int(m.group(3)), month, int(m.group(2)))
        return "INVALID"

    return "INVALID"

import re
from datetime import date

_FULL_MONTHS = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTH_LOOKUP = {}
for _i, _name in enumerate(_FULL_MONTHS, start=1):
    _MONTH_LOOKUP[_name] = _i
    _MONTH_LOOKUP[_name[:3]] = _i
_MONTH_LOOKUP["sept"] = 9

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "thurs "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|weds|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)


def _make(y: int, m: int, d: int):
    """Return ISO string for a valid calendar date, else None."""
    try:
        return date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_from_name(name: str):
    return _MONTH_LOOKUP.get(name.lower().rstrip("."))


def _strip_weekday(t: str) -> str:
    return _WEEKDAY_PREFIX.sub("", t, count=1)


def _iso(t: str):
    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))
    # YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None


def _numeric(t: str):
    # D/M/YYYY or M/D/YYYY with -, /, or . separators.
    # Unambiguous cases are resolved by range; ambiguous cases default to day-first.
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if not m:
        return None
    a, b, y = int(m.group(1)), int(m.group(3)), int(m.group(4))
    if a > 12 and b <= 12:
        day, month = a, b      # day-first, unambiguous
    elif b > 12 and a <= 12:
        day, month = b, a      # month-first, unambiguous
    else:
        day, month = a, b      # ambiguous (or invalid): default to day-first
    return _make(y, month, day)


def _month_name_first(t: str):
    # March 5, 2021 / Mar 5 2021 / March 5th, 2021
    m = re.fullmatch(r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", t, re.IGNORECASE)
    if not m:
        return None
    month = _month_from_name(m.group(1))
    if month is None:
        return None
    return _make(int(m.group(3)), month, int(m.group(2)))


def _day_name_first(t: str):
    # 5 March 2021 / 5th-Mar-2021 / 5 Mar, 2021
    m = re.fullmatch(r"(\d{1,2})(?:st|nd|rd|th)?[\s\-]+([A-Za-z]+)\.?,?[\s\-]+(\d{4})", t, re.IGNORECASE)
    if not m:
        return None
    month = _month_from_name(m.group(2))
    if month is None:
        return None
    return _make(int(m.group(3)), month, int(m.group(1)))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    # Weekday names carry no date information; drop them if present.
    t = _strip_weekday(t)
    if not t:
        return "INVALID"

    for handler in (_iso, _numeric, _month_name_first, _day_name_first):
        result = handler(t)
        if result is not None:
            return result
    return "INVALID"

