    r"friday|fri|saturday|sat|sunday|sun)\.?,?\s+"
)
_ORDINAL = re.compile(r"(\d{1,2})(st|nd|rd|th)\b")


def _year(text: str) -> int:
    y = int(text)
    if len(text) == 2:
        # Two-digit years: 00-69 -> 2000s, 70-99 -> 1900s.
        y += 2000 if y <= 69 else 1900
    return y


def _make(y: int, m: int, d: int) -> str:
    try:
        dt = date(y, m, d)
    except ValueError:
        return "INVALID"
    return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}"


def parse(s: str) -> str:
    text = " ".join(s.strip().lower().split())
    text = _WEEKDAY_PREFIX.sub("", text)
    text = _ORDINAL.sub(r"\1", text)

    # ISO-like, year first: 2024-03-05, 2024/3/5, 2024.03.05
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", text)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Compact: 20240305
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", text)
    if m:
        return _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric, day first: 29/02/2000, 05-03-24, 5.3.2024
    m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})", text)
    if m:
        return _make(_year(m.group(3)), int(m.group(2)), int(m.group(1)))

    # Month name, day, year: Nov 31 2022, November 31, 2022
    m = re.fullmatch(r"([a-z]+)\.?\s+(\d{1,2}),?\s+(\d{4}|\d{2})", text)
    if m and m.group(1) in _MONTHS:
        return _make(_year(m.group(3)), _MONTHS[m.group(1)], int(m.group(2)))

    # Day, month name, year: 31 Nov 2022, 31-Nov-2022, 31 november, 2022
    m = re.fullmatch(r"(\d{1,2})[\s\-/.]+([a-z]+)\.?,?[\s\-/.]+(\d{4}|\d{2})", text)
    if m and m.group(2) in _MONTHS:
        return _make(_year(m.group(3)), _MONTHS[m.group(2)], int(m.group(1)))

    # Year, month name, day: 2022 Nov 31
    m = re.fullmatch(r"(\d{4})[\s\-/.]+([a-z]+)\.?[\s\-/.]+(\d{1,2})", text)
    if m and m.group(2) in _MONTHS:
        return _make(int(m.group(1)), _MONTHS[m.group(2)], int(m.group(3)))

    return "INVALID"

