    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _iso(m.group(1), int(m.group(3)), int(m.group(4)))

    # YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _iso(m.group(1), int(m.group(2)), int(m.group(3)))

    # Numeric DD?MM?YYYY (or MM?DD?YYYY when the first part is > 12)
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        a, b, year = int(m.group(1)), int(m.group(3)), m.group(4)
