    m = re.fullmatch(
        rf"(\d{{1,2}}){_ORD}(?:\s+of)?\s+([a-z]+\.?)\s*,?\s*(\d{{4}})",
        t,
        re.IGNORECASE,
    )
    if m:
        month = _month_number(m.group(2))
        if month is None:
            return "INVALID"
        return _iso(m.group(3), month, int(m.group(1)))

    # March 5th, 2024 / June 31, 2021 / Sept. 5 2024
    m = re.fullmatch(
        rf"([a-z]+\.?)\s+(\d{{1,2}}){_ORD},?\s*(\d{{4}})",
        t,
        re.IGNORECASE,
    )
