import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "tues ".
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+"
)

# Year-first ISO: 2024-03-05 or 2024/3/5
_ISO = re.compile(r"(\d{4})([-/])(\d{1,2})\2(\d{1,2})")
# Numeric, day-first (ambiguous numerics are read as DD/MM/YYYY): 05/03/2024, 31.12.1999, 5-3-2024
_NUMERIC_DMY = re.compile(r"(\d{1,2})([/.\-])(\d{1,2})\2(\d{4})")
# "5 March 2024", "5th mar. 2024"
_DMY = re.compile(r"(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]+)\.?,?\s+(\d{4})")
# "March 5, 2024", "mar 5th 2024"
_MDY = re.compile(r"([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})")


def _build(year: int, month: int, day: int) -> str:
    try:
        d = date(year, month, day)
    except ValueError:
        return "INVALID"
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}"


def _normalize(s: str) -> str:
    text = " ".join(s.strip().lower().split())
    text = _WEEKDAY_PREFIX.sub("", text, count=1)
    text = text.rstrip(".").strip()
    return text


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = _normalize(s)
    if not text:
        return "INVALID"

    m = _ISO.fullmatch(text)
    if m:
        return _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    m = _NUMERIC_DMY.fullmatch(text)
    if m:
        return _build(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    m = _DMY.fullmatch(text)
    if m:
        month = _MONTHS.get(m.group(2))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(1)))

    m = _MDY.fullmatch(text)
    if m:
        month = _MONTHS.get(m.group(1))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(2)))

    return "INVALID"
